INSERT INTO feature VALUES('bicontextual-core','checking','The bicontextual core',NULL,'partial','notable',NULL,'One judgement with a supplied environment flowing in and a demanded support flowing out, polarity routing each binding: every core node carries its exact support as a compact word code, which the check memo keys its judgements by (#673, #705, #732, #750, #785, #866), and a `reads` claim states the items a declaration''s footprint names, settled against the footprint its content table carries (#2520).','core-term core-sequent core-incremental kernel-core','crates/core-term/src/support/tests.rs crates/core-term/src/arena/tests.rs crates/core-sequent/src/il/tests.rs crates/core-incremental/tests/supports.rs crates/core-incremental/src/content/tests.rs crates/core-incremental/src/codec/tests.rs crates/kernel-core/tests/acceptance.rs crates/surface-dispatcher/tests/corpus.rs::a_reads_claim_settles_against_the_carried_footprint_2520','corpus/ledger/features/bicontextual-core.gandr','#340 #3123');
